import test from 'node:test';
import assert from 'node:assert/strict';
import { buildFallbackChartData } from './chartFallback.js';
test('buildFallbackChartData returns a valid synthetic chart payload', () => {
    const chart = buildFallbackChartData('AAPL', '1y', '1d', 180.5);
    assert.ok(chart);
    assert.ok(chart.meta);
    assert.ok(Array.isArray(chart.quotes));
    assert.ok(chart.quotes.length > 0);
    assert.equal(chart.meta.symbol, 'AAPL');
    assert.equal(chart.meta.range, '1y');
    assert.equal(chart.meta.interval, '1d');
    const first = chart.quotes[0];
    assert.ok(first.date);
    assert.ok(typeof first.open === 'number');
    assert.ok(typeof first.high === 'number');
    assert.ok(typeof first.low === 'number');
    assert.ok(typeof first.close === 'number');
    assert.ok(typeof first.volume === 'number');
});
